package dev.starfold;

import dev.starfold.BentStripGeometry.Point;
import dev.starfold.CubeSurfaceTopology.Face;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

/** Offline geometry and rendering contracts, not GPU/visual acceptance. */
class NativeGroundExteriorTest {
    NativeGroundExteriorMesh.Heights heights(double edited){return new NativeGroundExteriorMesh.Heights(){public double node(Face f,int x,int z){return 0;}public Double edited(Face f,int x,int z){return f==Face.TOP&&x==255&&z==255?edited:null;}};}
    @Test void highMountainAndDeepPitAreActualGeometryEvenForOneColumn(){for(double h:new double[]{191,-190}){var p=NativeGroundExteriorMesh.centre(heights(h),Face.TOP,255,255);assertEquals(GroundOrbit.RADIUS+h,p.length(),1e-9);assertTrue(p.finite());}}
    @Test void fineNodesMatchCoarseChordsWithoutTjunctionCracks(){var source=heights(0);for(int x=0;x<=16;x++){var a=NativeGroundExteriorMesh.position(Face.TOP,1024,1024,0);var b=NativeGroundExteriorMesh.position(Face.TOP,1040,1024,0);var p=NativeGroundExteriorMesh.node(source,Face.TOP,1024+x,1024);assertEquals(0,p.sub(a.scale(1-x/16.0).add(b.scale(x/16.0))).length(),1e-9);}}
    @Test void editedColumnDisplacesBothItsSharedBoundaryNodes(){var source=heights(191);for(int z:new int[]{255,256}){var a=NativeGroundExteriorMesh.node(source,Face.TOP,256,z);assertTrue(a.length()>GroundOrbit.RADIUS+40);assertEquals(47.75,a.sub(NativeGroundExteriorMesh.baseline(source,Face.TOP,256,z)).length(),1e-9);}}
    @Test void allFaceSeamsAndCornersRemainIdenticalIncludingEdits(){var source=new NativeGroundExteriorMesh.Heights(){public double node(Face f,int x,int z){return 0;}public Double edited(Face f,int x,int z){return f==Face.TOP?150.0:-70.0;}};
        int compared=0;for(var f:Face.values())for(int x:new int[]{0,16,1024,2032,2048})for(int z:new int[]{0,16,1024,2032,2048}){if(x!=0&&x!=2048&&z!=0&&z!=2048)continue;var cube=f.normal.scale(1024).add(f.u.scale(x-1024)).add(f.v.scale(z-1024));for(var g:Face.values())if(g!=f&&cube.dot(g.normal)==1024){var a=NativeGroundExteriorMesh.node(source,f,x,z);var b=NativeGroundExteriorMesh.node(source,g,(int)(1024+cube.dot(g.u)),(int)(1024+cube.dot(g.v)));assertEquals(0,a.sub(b).length(),1e-9);compared++;}}
        assertTrue(compared>100);
    }
    @Test void bakedFullOrbitVerticesAgreeWithPreviousFullCurvatureTransform(){var pose=new GroundSpace.Pose(Face.EAST,new Point(750,1700,890));var eye=pose.point();var orbit=new GroundOrbit(pose,eye,128);for(var f:Face.values())for(int x:new int[]{0,256,1024,2048})for(int z:new int[]{0,256,1024,2048}){var position=NativeGroundExteriorMesh.position(f,x,z,120);var draw=orbit.observerFrame.local(position).add(new Point(eye.x(),-GroundOrbit.RADIUS,eye.z())).add(orbit.offset);assertEquals(0,draw.sub(orbit.point(f,new Point(x,120,z))).length(),1e-8);}}
    @Test void selectionHysteresisCannotFlickerAroundTheEntryHeight(){assertFalse(NativeGroundExteriorMesh.select(false,true,1080));assertTrue(NativeGroundExteriorMesh.select(false,true,1088));assertTrue(NativeGroundExteriorMesh.select(true,true,1040));assertFalse(NativeGroundExteriorMesh.select(true,true,1023));assertFalse(NativeGroundExteriorMesh.select(true,false,2000));}
    @Test void exteriorShadersExportVanillaAndVeilForActualLinking()throws Exception{var root=Path.of("src/main/resources/assets/starfold/shaders/core");var out=Path.of("build/native-exterior/shaders");Files.createDirectories(out);for(String ext:List.of("vsh","fsh")){String text=Files.readString(root.resolve("native_ground_exterior."+ext));String suffix=ext.equals("vsh")?"vert":"frag";Files.writeString(out.resolve("exterior."+suffix),text);var parsed=io.github.ocelot.glslprocessor.api.GlslParser.preprocessParse(text,new HashMap<>());Files.writeString(out.resolve("exterior-veil."+suffix),parsed.toSourceString());}}
    @Test void farShaderHasNoAtlasSamplingInverseProjectionOrGroundWarp()throws Exception{var root=Path.of("src/main/resources/assets/starfold/shaders/core");var v=Files.readString(root.resolve("native_ground_exterior.vsh"));var f=Files.readString(root.resolve("native_ground_exterior.fsh"));assertFalse(v.contains("inverse("));assertFalse(v.contains("cpNativeOrbitRepair"));assertFalse(f.contains("texture"));assertFalse(f.contains("dFdx"));assertTrue(f.contains("SunBody-bodyPosition"));assertTrue(f.contains("1.0)"));}
    @Test void onlyCompleteExteriorTakesOverAndOldPatchStaysUntilReplacement()throws Exception{var s=Files.readString(Path.of("src/main/java/dev/starfold/NativeGroundRenderer.java"));assertTrue(s.contains("ready&&NativeGroundExterior.ready()"));assertTrue(s.contains("if(replacesNative()){if(!translucent)NativeGroundExterior.draw(c);return;}"));assertTrue(s.contains("tile==256&&exterior.done()"));assertTrue(s.contains("dirtyHalo(key)"));assertTrue(s.contains("NativeGroundPipeline.publish(dirty.count(),coverJob!=null,patches,staging)"));var exterior=Files.readString(Path.of("src/main/java/dev/starfold/NativeGroundExterior.java"));assertTrue(exterior.contains("staging[patch]=mesh"));assertTrue(exterior.contains("patches[i]=staging[i]"));}
}
